class Inventory:
    def __init__(self, stock):
        self.stock = dict(stock)
        self.requests = {}

    def reserve(self, request_id, lines):
        if request_id in self.requests:
            return self.requests[request_id] == self._aggregate(lines)
        aggregate = self._aggregate(lines)
        if aggregate is None:
            return False
        for sku, n in aggregate.items():
            if self.stock.get(sku, 0) < n:
                return False
        for sku, n in aggregate.items():
            self.stock[sku] -= n
        self.requests[request_id] = aggregate
        return True

    def cancel(self, request_id):
        if request_id not in self.requests:
            return False
        for sku, n in self.requests[request_id].items():
            self.stock[sku] += n
        del self.requests[request_id]
        return True

    def snapshot(self):
        return dict(self.stock)

    @staticmethod
    def _aggregate(lines):
        total = {}
        for sku, n in lines:
            if not isinstance(sku, str) or not isinstance(n, int) or n <= 0:
                return None
            total[sku] = total.get(sku, 0) + n
        return total

